//! Emits `desktop/web/src/generated/file-kinds.ts` from `canopi_types::dialog::FileKind::ALL`
//! (contracts §16, 2.1-M155, 2.1-M522).

use std::error::Error;
use std::fmt::Write;

use canopi_types::dialog::FileKind;

pub(crate) fn render_file_kinds_ts() -> Result<String, Box<dyn Error>> {
    let mut out = String::new();
    writeln!(
        out,
        "// Generated by `cargo run -p bindings-gen` from `canopi-types/src/dialog.rs`."
    )?;
    writeln!(out, "// Do not edit by hand.")?;
    writeln!(out)?;
    writeln!(out, "import type {{ FileKind }} from './contracts'")?;
    writeln!(out)?;
    writeln!(out, "export interface FileKindMeta {{")?;
    writeln!(out, "  readonly extensions: readonly string[]")?;
    writeln!(out, "  readonly mimeType: string")?;
    writeln!(out, "  readonly filterLabel: string")?;
    writeln!(out, "}}")?;
    writeln!(out)?;
    writeln!(
        out,
        "export const FILE_KINDS: Readonly<Record<FileKind, FileKindMeta>> = {{"
    )?;
    for kind in FileKind::ALL {
        let exts = kind
            .extensions()
            .iter()
            .map(|e| format!("'{e}'"))
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(
            out,
            "  '{}': {{ extensions: [{exts}], mimeType: '{}', filterLabel: '{}' }},",
            kind.literal(),
            kind.mime_type(),
            kind.filter_label(),
        )?;
    }
    writeln!(out, "}} as const")?;
    Ok(out)
}
